constexpr const BlockInfo& info(BlockType t) { return kBlocks[static_cast<std::size_t>(t)]; }

constexpr bool findBlockType(std::string_view id, BlockType& out) {
  for (const auto& b : kBlocks) if (b.id == id) { out = b.type; return true; }
  return false;
}

